async function replyToComment(input) {
  if (input.platform === "THREADS") {
    return publishThreads({ caption: input.message, replyToId: input.commentId, channel: input.channel });
  }
  if (input.platform === "FACEBOOK") {
    return commentFacebook({ postId: input.commentId, message: input.message, channel: input.channel });
  }
  if (input.platform === "YOUTUBE") return replyYoutubeComment(input);
  const { token, error: error2 } = await loadTokenFile("INSTAGRAM", input.channel);
  if (!token) return error2;
  const create = await graphRequest("post", `${IG_BASE}/${input.commentId}/replies`, {
    message: input.message,
    access_token: token
  });
  if (!create.ok) return create;
  const replyId = str4(parseJson(create.body)?.id);
  if (!replyId) return fail2(502, `Instagram reply returned no id: ${create.body}`);
  return okJson({ platform: "INSTAGRAM", replyId, permalink: null });
}
async function replyYoutubeComment(input) {
  const { client, error: clientError } = await loadYoutubeClient(input.channel);
  if (!client) return clientError;
  const { token, error: tokenError } = await exchangeYoutubeAccessToken(client);
  if (!token) return tokenError;
  const lookup = await youtubeRequest(
    "get",
    `${YT_DATA_BASE}/comments`,
    { part: "snippet", id: input.commentId },
    token
  );
  if (!lookup.ok) return withYoutubeScopeHint(lookup, "youtube.force-ssl");
  const found = parseJson(lookup.body)?.items?.[0];
  if (!found) return fail2(404, `YouTube comment not found: ${input.commentId}`);
  const parentId = str4(found.snippet?.parentId) || input.commentId;
  const created = await youtubeRequest(
    "post",
    `${YT_DATA_BASE}/comments`,
    { part: "snippet" },
    token,
    { snippet: { parentId, textOriginal: input.message } }
  );
  if (!created.ok) return withYoutubeScopeHint(created, "youtube.force-ssl");
  const replyId = str4(parseJson(created.body)?.id);
  if (!replyId) return fail2(502, `YouTube comment insert returned no id: ${created.body}`);
  return okJson({
    platform: "YOUTUBE",
    replyId,
    // A request made with a nested reply's id lands on a different parent — report where it attached
    parentCommentId: parentId,
    permalink: null
  });
}
